unordered_map<int, int> freq;
int distinct = 0;

// Initialize
for (int i = 0; i < k; i++) {
    if (++freq[arr[i]] == 1) {
        distinct++;
    }
}

for (int i = k; i < n; i++) {

    if (++freq[arr[i]] == 1) {
        distinct++;
    }

    if (--freq[arr[i - k]] == 0) {
        distinct--;
    }

    // `distinct` is the number of unique values in the current window

}
